sys_script_include.script:
var Position_Retry_Outbound = Class.create();
Position_Retry_Outbound.prototype = {
    initialize: function() {},
    checkEnvironmentSummary: function() {
        var intervalSum = gs.getProperty("x_hsb11_mss_pos.retry_position_interval_environment_check_summary");
        var uri_prop_sum = gs.getProperty("x_hsb11_mss_pos.hsbcmss_el_custodyPositionSummaryonDemand_api_url");
        var responseStatusFilterSum = gs.getProperty("x_hsb11_mss_pos.Position_status_code_summary");
        var gr = new GlideRecord("sys_outbound_http_log");
        gr.addQuery("response_status", "NOT IN", responseStatusFilterSum.split(','));
        gr.addEncodedQuery(intervalSum);
        gr.addQuery("url", "STARTSWITH", uri_prop_sum);
        gr.query();
        if (gr.hasNext()) {
            return false;
        } else {
            return true;
        }
    },

    checkEnvironmentDetail: function() {
        var intervalDet = gs.getProperty("x_hsb11_mss_pos.retry_position_interval_environment_check_detail");
        var uri_prop_Det = gs.getProperty("x_hsb11_mss_pos.hsbcmss_el_custodyPositionDetailonDemand_api_url");
        var responseStatusFilterDet = gs.getProperty("x_hsb11_mss_pos.Position_status_code_detail");
        var gr = new GlideRecord("sys_outbound_http_log");
        gr.addQuery("response_status", "NOT IN", responseStatusFilterDet.split(','));
        gr.addEncodedQuery(intervalDet);
        gr.addQuery("url", "STARTSWITH", uri_prop_Det);
        gr.query();
        if (gr.hasNext()) {
            return false;
        } else {
            return true;
        }
    },



    retrySummary: function() {
        var retry_cnt_sum = gs.getProperty("x_hsb11_mss_pos.position_retry_count_summary");
        var responseStatusFilter = gs.getProperty("x_hsb11_mss_pos.Position_status_code_summary");
        var gr = new GlideRecord("x_hsb11_mss_pos_mss_custody_position_ondemand_staging");
        gr.addQuery("state_for_summary", "error");
        gr.addQuery("response_code_for_summary", "NOT IN", responseStatusFilter.split(','));
        gr.addQuery("retry_count_for_summary", "<", retry_cnt_sum);
        gr.query();
        while (gr.next()) {
            gr.state_for_summary = "ready_to_be_sent";
            gr.retry_count_for_summary = gr.retry_count_for_summary + 1;
            gr.update();
        }
    },

    retryDetail: function() {
        var retry_cnt_det = gs.getProperty("x_hsb11_mss_pos.position_retry_count_detail");
        var responseStatusFilter = gs.getProperty("x_hsb11_mss_pos.Position_status_code_detail");
        var gr = new GlideRecord("x_hsb11_mss_pos_mss_custody_position_ondemand_staging");
        gr.addQuery("state_for_detail", "error");
        gr.addQuery("response_code_for_detail", "NOT IN", responseStatusFilter.split(','));
        gr.addQuery("retry_count_for_detail", "<", retry_cnt_det);
        gr.query();
        while (gr.next()) {
            gr.state_for_detail = "ready_to_be_sent";
            gr.retry_count_for_detail = gr.retry_count_for_detail + 1;
            gr.update();
        }
    },

    type: 'Position_Retry_Outbound'
};
